def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        if i == n:
            # End of line - add the last field
            fields.append("")
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ""
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote - represents one quote character
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i == n or line[i] == ',':
                            fields.append(field)
                            if i < n:
                                i += 1  # Skip the comma
                            break
                        else:
                            # Invalid: closing quote not followed by comma or end
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None
        else:
            # Unquoted field
            field = ""
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Double quote not allowed in unquoted field
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < n:
                i += 1  # Skip the comma

    return fields

